//! Isolated experiment: freeze the AVX-512 f64 `24 x 8` real micro-kernel's
//! compiler-generated assembly and A/B it against the intrinsic kernel.
//!
//! The kernel under test is
//! [`tcontract_kernel::kernels::x86::avx512_f64::real::<3,8>`], the `MR = 3*8 = 24`
//! by `NR = 8` f64 tile product the packed driver runs (family id
//! `avx512.f64.real.24x8`). Its body is generated by `simd_kernels!` in
//! `crates/tcontract-kernel/src/kernels/macros.rs` and instantiated for
//! `avx512_f64` in `crates/tcontract-kernel/src/kernels/x86/avx512.rs`.
//!
//! `real::<3,8>` is `#[target_feature(enable = "avx512f")]`, so a plain
//! function cannot call it directly; the driver reaches it through the
//! function-pointer trampoline `tramp_real::<3,8>`. Under
//! `-C target-cpu=native` LLVM inlines `real` into `tramp_real`, so the
//! trampoline *is* the whole kernel body (this is what `freeze.sh` copies into
//! `asm/avx512_f64_real_24x8.S`). See `README.md` and `PROVENANCE.md`.
//!
//! # Safety
//!
//! Both kernels are `unsafe`: they take raw pointers and require the CPU to
//! support AVX-512F. Callers uphold the tile contract documented on each.

use tcontract_kernel::kernels::x86::cfg_avx512_f64;

/// Register rows of the micro-tile (`MR = MV * L = 3 * 8`).
pub const MR: usize = 24;
/// Register columns of the micro-tile.
pub const NR: usize = 8;

/// The common callable shape of both kernels.
pub type Ukr = unsafe fn(usize, *const f64, *const f64, *mut f64);

extern "Rust" {
    /// The frozen compiler-generated body of `real::<3,8>` (native build), with
    /// the symbol renamed to `frozen_real_24x8`. Assembled from
    /// `asm/avx512_f64_real_24x8.S` by `build.rs`. Declared with the `"Rust"`
    /// ABI (identical to `"C"` for this signature on x86-64 SysV) so the fn
    /// item coerces directly to [`Ukr`].
    ///
    /// # Safety
    /// See the header comment of `asm/avx512_f64_real_24x8.S`: `a` must be valid
    /// for `24 * kc`, `b` for `8 * kc`, `ab` for `24 * 8` reads/writes, none
    /// aliasing; the CPU must support AVX-512F.
    fn frozen_real_24x8(kc: usize, a: *const f64, b: *const f64, ab: *mut f64);
}

/// The intrinsic kernel as a function pointer: the exact monomorphization the
/// packed driver stores in its `Ukr` (`tramp_real::<3,8>`, instantiated inside
/// `tcontract-kernel` by the `configs!` menu — the `_EBa_` symbol `freeze.sh`
/// froze). Reached through `real_config().ukr.func` so no fresh monomorphization
/// (and no differing codegen) is introduced in this crate.
pub fn intrinsic_ukr() -> Ukr {
    cfg_avx512_f64::real_config().ukr.func
}

/// The frozen-assembly kernel as a function pointer.
pub fn frozen_ukr() -> Ukr {
    frozen_real_24x8
}

/// Naive column-major reference for the tile contract
/// `ab[j*MR + i] = sum_p a[p*MR + i] * b[p*NR + j]`.
pub fn reference_real(kc: usize, a: &[f64], b: &[f64]) -> Vec<f64> {
    assert_eq!(a.len(), MR * kc);
    assert_eq!(b.len(), NR * kc);
    let mut c = vec![0.0f64; MR * NR];
    for p in 0..kc {
        for i in 0..MR {
            let av = a[p * MR + i];
            for j in 0..NR {
                c[j * MR + i] += av * b[p * NR + j];
            }
        }
    }
    c
}
